### Step 5: Add `Convention::is_checkable()` in `engine.rs`

```rust
impl Convention {
    pub fn is_checkable(&self, toolchain_pairs: &[ToolchainPair]) -> bool {
        use crate::conventions::attributes::{classify_attribute, AttributeRole};

        // All consequents must be obligations
        let consequents_ok = self.consequent.iter().all(|c| {
            classify_attribute(c) == AttributeRole::Obligation
        });
        if !consequents_ok {
            return false;
        }

        // Antecedents must be identity or obligation (both allowed)
        // — this is always true by exhaustive enum, but documents the constraint

        // Exclude toolchain-enforced pairs
        for pair in toolchain_pairs {
            if self.antecedent.iter().any(|a| a == pair.antecedent)
                && self.consequent.iter().any(|c| c == pair.consequent)
                && self.consequent.len() == 1
            {
                return false;
            }
        }

        true
    }
}
```

