### Step 7: Unit tests for role classification

In `src/conventions/attributes.rs` tests module:

```rust
#[test]
fn classify_identity_attributes() {
    use super::*;
    assert_eq!(classify_attribute("kind:function"), AttributeRole::Identity);
    assert_eq!(classify_attribute("kind:struct"), AttributeRole::Identity);
    assert_eq!(classify_attribute("vis:pub"), AttributeRole::Identity);
    assert_eq!(classify_attribute("vis:private"), AttributeRole::Identity);
    assert_eq!(classify_attribute("in:src/db"), AttributeRole::Identity);
    assert_eq!(classify_attribute("is_method"), AttributeRole::Identity);
    assert_eq!(classify_attribute("has_sig"), AttributeRole::Identity);
    assert_eq!(classify_attribute("complexity:high"), AttributeRole::Identity);
}

#[test]
fn classify_obligation_attributes() {
    use super::*;
    assert_eq!(classify_attribute("has_doc"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("naming:snake_case"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("naming:CamelCase"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("returns_result"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("returns_option"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("is_async"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("effect:io"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("effect:db"), AttributeRole::Obligation);
    assert_eq!(classify_attribute("returns_future"), AttributeRole::Obligation);
}
```

### Step 8: Unit tests for `is_checkable` filter

In `src/conventions/engine.rs` tests module:

```rust
#[test]
fn is_checkable_excludes_tautological_convention() {
    // in:src/db → kind:function is identity → identity — not checkable
    let conv = Convention {
        id: Arc::from("test-tautology"),
        antecedent: Arc::from(vec!["in:src/db".into()]),
        consequent: Arc::from(vec!["kind:function".into()]),
        support: 10, confidence: 0.9,
        component_id: None,
    };
    assert!(!conv.is_checkable(&[]));
}

#[test]
fn is_checkable_excludes_backwards_convention() {
    // has_doc → vis:pub is obligation → identity — not checkable
    let conv = Convention {
        id: Arc::from("test-backwards"),
        antecedent: Arc::from(vec!["has_doc".into()]),
        consequent: Arc::from(vec!["vis:pub".into()]),
        support: 10, confidence: 0.9,
        component_id: None,
    };
    assert!(!conv.is_checkable(&[]));
}

#[test]
fn is_checkable_allows_vis_pub_implies_has_doc() {
    // vis:pub → has_doc is identity → obligation — checkable
    let conv = Convention {
        id: Arc::from("test-valid"),
        antecedent: Arc::from(vec!["vis:pub".into()]),
        consequent: Arc::from(vec!["has_doc".into()]),
        support: 10, confidence: 0.9,
        component_id: None,
    };
    assert!(conv.is_checkable(&[]));
}

#[test]
fn is_checkable_excludes_toolchain_enforced() {
    use crate::parser::adapter::ToolchainPair;
    let conv = Convention {
        id: Arc::from("test-toolchain"),
        antecedent: Arc::from(vec!["kind:function".into()]),
        consequent: Arc::from(vec!["naming:snake_case".into()]),
        support: 50, confidence: 1.0,
        component_id: None,
    };
    let pairs = &[ToolchainPair {
        antecedent: "kind:function",
        consequent: "naming:snake_case",
    }];
    assert!(!conv.is_checkable(pairs));
}
